  @doc "Returns pinned UAX29 grapheme and Indic conjunct break properties for an admitted scalar."
  @spec grapheme_break(non_neg_integer()) :: {atom(), atom()}
  def grapheme_break(codepoint) do
    if codepoint < 128,
      do: elem(@grapheme_ascii, codepoint),
      else: find(codepoint, @grapheme_ranges, 0, tuple_size(@grapheme_ranges) - 1)
  end

  @typedoc "Script, bidi class, category, combining class, joining type, Indic category/position and vertical orientation."
  @type properties ::
          {binary(), atom(), atom(), non_neg_integer(), atom(), atom(), atom(), atom()}

  @doc "Returns pinned Unicode text-layout properties for a scalar."
  @spec properties(non_neg_integer()) :: properties()
  def properties(codepoint) do
    if codepoint < 128,
      do: elem(@ascii, codepoint),
      else: find(codepoint, @ranges, 0, tuple_size(@ranges) - 1)
  end

  @doc "Returns the Script_Extensions candidates, or the scalar's Script."
  @spec scripts(non_neg_integer()) :: tuple()
  def scripts(codepoint) do
    find(codepoint, @extensions, 0, tuple_size(@extensions) - 1) ||
      {elem(properties(codepoint), 0)}
  end

  @doc "Returns the bidirectional mirrored scalar, retaining a scalar without a mapping."
  @spec mirror(non_neg_integer()) :: non_neg_integer()
  def mirror(codepoint), do: Map.get(@mirrors, codepoint, codepoint)

  @doc "Returns the paired bracket and its opening or closing role."
  @spec bracket(non_neg_integer()) :: {non_neg_integer(), :open | :close} | nil
  def bracket(codepoint), do: Map.get(@brackets, codepoint)

  @doc "Identifies Unicode emoji presentation participating scalars with standardized VS15/VS16 sequences."
  @spec emoji_variant?(non_neg_integer()) :: boolean()
  def emoji_variant?(codepoint), do: MapSet.member?(@emoji_variants, codepoint)

  @doc "Identifies the Ambiguous East Asian Width class for CSS CJK line-break tailoring."
  @spec ambiguous_width?(non_neg_integer()) :: boolean()
  def ambiguous_width?(codepoint),
    do: find(codepoint, @ambiguous_width, 0, tuple_size(@ambiguous_width) - 1) || false

  @doc "Returns the pinned line-break class and East Asian width participation used by UAX14."
  @spec line_break(non_neg_integer()) :: {atom(), boolean()}
  def line_break(codepoint) do
    if codepoint < 128,
      do: elem(@break_ascii, codepoint),
      else: find(codepoint, @break_ranges, 0, tuple_size(@break_ranges) - 1)
  end

  defp find(codepoint, records, low, high) do
    if low > high do
      nil
    else
      index = div(low + high, 2)
      {first, last, value} = elem(records, index)

      cond do
        codepoint < first -> find(codepoint, records, low, index - 1)
        codepoint > last -> find(codepoint, records, index + 1, high)
        true -> value
      end
    end
  end
end
